/**
 * Stateful entry point for the pushed `deepDiveDetail/{symbol}` destination -- reached only from
 * the Deep Dive banner on Stock Detail, per the confirmed decision that Deep Dive opens as its own
 * full screen rather than an added tab. Own header (back arrow + symbol + "Deep Dive" title + the
 * authoritative `deep_analysis_date`, not the preview's denormalized copy), not a Material
 * `TopAppBar` -- same reasoning and `windowInsetsPadding(WindowInsets.statusBars)` handling as
 * `StockDetailRoute` (see `MainActivity`'s `isPushedDestination`, which excludes this route from
 * the global collapsing top bar too).
 */
@Composable
fun DeepDiveRoute(
    scaffoldPadding: PaddingValues,
    onNavigateUp: () -> Unit,
    viewModel: DeepDiveViewModel = hiltViewModel()
) {
    val uiState by viewModel.uiState.collectAsStateWithLifecycle()
    val snackbarHostState = remember { SnackbarHostState() }
    val lifecycleOwner = LocalLifecycleOwner.current
    val pulseColors = LocalPulseColors.current

    DisposableEffect(lifecycleOwner) {
        val observer = LifecycleEventObserver { _, event ->
            if (event == Lifecycle.Event.ON_START) viewModel.onStart()
        }
        lifecycleOwner.lifecycle.addObserver(observer)
        onDispose { lifecycleOwner.lifecycle.removeObserver(observer) }
    }

    LaunchedEffect(uiState.error) {
        uiState.error?.message?.let { message ->
            if (uiState.deepDive != null) {
                // A deep dive is already on screen -- a background refresh failure is a soft
                // error, surfaced as a toast rather than replacing content that's still good.
                snackbarHostState.showSnackbar(message)
                viewModel.clearError()
            }
            // No deep dive cached at all: leave the error set so the persistent error state below
            // stays up until the user retries (fetchDeepDive clears it itself on the next attempt).
        }
    }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .windowInsetsPadding(WindowInsets.statusBars)
    ) {
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .background(MaterialTheme.colorScheme.background)
                .padding(dimensionResource(id = R.dimen.padding_large))
        ) {
            Row(
                verticalAlignment = Alignment.CenterVertically,
                modifier = Modifier.clickable(onClick = onNavigateUp)
            ) {
                Icon(
                    painter = painterResource(id = R.drawable.ic_back),
                    contentDescription = stringResource(id = R.string.nav_back_content_description),
                    tint = pulseColors.onSurfaceMuted
                )
                Spacer(modifier = Modifier.width(dimensionResource(id = R.dimen.padding_small)))
                // 💡 "{symbol} · ANALYSIS" -- reuses DetailHeader's own back-label copy
                // (`stock_detail_back_label`, "ANALYSIS") rather than a new duplicate string, since
                // this screen is one level deeper than Stock Detail's own "< ANALYSIS" back row.
                Text(
                    text = "${uiState.symbol} · ${stringResource(id = R.string.stock_detail_back_label)}",
                    style = MaterialTheme.typography.bodyMedium,
                    color = pulseColors.onSurfaceMuted
                )
            }
            Spacer(modifier = Modifier.height(dimensionResource(id = R.dimen.padding_large)))
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Text(
                    text = stringResource(id = R.string.deep_dive_title),
                    style = MaterialTheme.typography.headlineMedium.copy(fontWeight = FontWeight.Bold),
                    color = MaterialTheme.colorScheme.onSurface
                )
                // 💡 One label for the whole page, not per DeepDiveSectionCard -- this screen
                // renders 9 section cards from one AI-authored Deep Dive; repeating the disclosure
                // on each would be noisy for something that applies to the page as a whole.
                AiGeneratedLabel()
            }
            uiState.previewName?.let { name ->
                Text(
                    text = "$name · ${uiState.symbol}",
                    style = MaterialTheme.typography.bodyMedium,
                    color = pulseColors.accentPrimary
                )
            }
            Spacer(modifier = Modifier.height(dimensionResource(id = R.dimen.padding_medium)))
            DeepDiveUpdatedAtLine(
                deepAnalysisDate = uiState.deepDive?.deepAnalysisDate,
                nextDeepDiveTriggerDate = uiState.deepDive?.nextDeepDiveTriggerDate,
                nextDeepDiveTriggerReason = uiState.deepDive?.nextDeepDiveTriggerReason
            )
        }

        Box(modifier = Modifier.fillMaxSize()) {
            val contentPadding = PaddingValues(
                bottom = scaffoldPadding.calculateBottomPadding() + dimensionResource(id = R.dimen.padding_large),
                start = dimensionResource(id = R.dimen.padding_large),
                end = dimensionResource(id = R.dimen.padding_large)
            )

            when {
                uiState.deepDive != null -> {
                    DeepDiveScreen(
                        sections = uiState.deepDive?.sections.orEmpty(),
                        fundamentalsDelta = uiState.deepDive?.fundamentalsDelta.orEmpty(),
                        isEmpty = false,
                        contentPadding = contentPadding
                    )
                }

                uiState.isLoading -> {
                    Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                        PulseLoadingIndicator()
                    }
                }

                uiState.error != null -> {
                    // Fetch failed and nothing is cached -- distinct from the true cold-start case
                    // below, which is a normal 404 (no deep dive has ever run for this symbol).
                    PulseErrorState(
                        message = uiErrorMessage(uiState.error!!),
                        onRetry = { viewModel.refresh() }
                    )
                }

                else -> {
                    // Cold start (no `detail/deep` doc yet) is the expected state here, not an
                    // error -- an honest empty message, never a skeleton stuck forever.
                    DeepDiveScreen(
                        sections = emptyList(),
                        fundamentalsDelta = emptyList(),
                        isEmpty = true,
                        contentPadding = contentPadding
                    )
                }
            }

            SnackbarHost(
                hostState = snackbarHostState,
                modifier = Modifier
                    .align(Alignment.BottomCenter)
                    .padding(bottom = scaffoldPadding.calculateBottomPadding())
            )
        }
    }
}
